        } else {
            actions.push({ type: 'skip',
                reason: 'approved but merge state ' + pr.mergeState });
        }
        return actions;
    }

    if (has('ai_developed') && !has('ai_pr_reviewed')) {
        actions.push({ type: 'dispatch', leg: 'review',
            reason: 'green PR #' + pr.number + ' awaits machine review' });
