        try {
            var result = file_read(readOpts);
            if (result) return result;
        } catch (e) {}
        if (p.indexOf('agents/') === 0) {
            try { return file_read({ path: p.substring('agents/'.length) }); } catch (e) {}
        }
        return null;
    };

